#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

typedef struct {
    unsigned char hash[32];
    unsigned char salt[32];
} HashedPassword;

int main() {
    // Test case with empty password
    const char* password = "";
    unsigned char salt[32];
    unsigned char hash[32];

    // Generate random salt
    if (RAND_bytes(salt, 32) != 1) {
        printf("Failed to generate salt\n");
        return EXIT_FAILURE;
    }

    // Test PBKDF2 HMAC with empty password
    if (!PKCS5_PBKDF2_HMAC(password, strlen(password),
                           salt, 32,
                           10000, EVP_sha256(),
                           hash)) {
        printf("PBKDF2 HMAC failed\n");
        return EXIT_FAILURE;
    }

    printf("Hash for empty password: ");
    for (int i = 0; i < 32; ++i) {
        printf("%02x", hash[i]);
    }
    printf("\n");

    return EXIT_SUCCESS;
}
